def decorate(canvas, doc):
    width, height = A4
    canvas.setStrokeColor(TEAL)
    canvas.setLineWidth(2)
    canvas.line(42, height - 30, width - 42, height - 30)
    canvas.setFont("Guide", 8)
    canvas.setFillColor(NAVY)
    canvas.drawString(42, 26, "СКЛАД КОМФОРТА / ПРАВИЛА И РАСЧЁТЫ")
    canvas.drawRightString(width - 42, 26, f"{doc.page} / 11")

doc = SimpleDocTemplate(str(OUT), pagesize=A4, rightMargin=42, leftMargin=42,
                        topMargin=48, bottomMargin=46, title="Правила и расчёты: руководство пользователя",
                        author="Склад Комфорта")
doc.build(story, onFirstPage=decorate, onLaterPages=decorate)
reader = PdfReader(OUT)
assert len(reader.pages) == 11, f"Unexpected pagination: {len(reader.pages)}"
for i, pg in enumerate(reader.pages):
    content = pg.extract_text()
    assert len(content) > 300, f"Empty page {i + 1}"
    assert '\ufffd' not in content
rendered = pdfium.PdfDocument(str(OUT))
for i in range(len(rendered)):
    rendered[i].render(scale=1.25).to_pil().save(QA / f"page-{i + 1:02d}.png")
print(f"Created {OUT}; verified and rendered {len(reader.pages)} pages")
